SELECT DATE_TRUNC('QUARTER', opened_date) AS quarter_start, COUNT(DISTINCT account_type) AS distinct_account_types, COUNT(*) FILTER (WHERE status = 'OPEN') AS open_rows, COUNT(DISTINCT customer_id) AS distinct_customer_ids, STDDEV_SAMP(balance) AS balance_stddev, APPROX_PERCENTILE(balance, ARRAY(0.25, 0.5, 0.75)) AS balance_quartiles, COUNT_IF(account_type = 'SAVINGS') AS savings_events FROM accounts GROUP BY DATE_TRUNC('QUARTER', opened_date) ORDER BY balance_stddev DESC;
